<?php require '../config.php';admin();$tickets=$db->query("SELECT t.*,u.email FROM tickets t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tickets</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="app"><?php include __DIR__ . "/_sidebar.php"; ?><main class="main"><h1>Support Tickets</h1><div class="card table-wrap"><table><tr><th>#</th><th>User</th><th>Subject</th><th>Message</th><th>Status</th></tr><?php while($t=$tickets->fetch_assoc()):?><tr><td><?=$t['id']?></td><td><?=e($t['email'])?></td><td><?=e($t['subject'])?></td><td><?=e($t['message'])?></td><td><?=e($t['status'])?></td></tr><?php endwhile;?></table></div></main></div></body></html>